/*
 Problem: 301. Remove Invalid Parentheses
 Language: cpp
 Runtime: 3 ms (74.41%)
 Memory: 10.8 MB (78.53%)
 Tags: String, Backtracking, Breadth-First Search
*/
class Solution {
public:
    vector<string> removeInvalidParentheses(string s) {
        vector<string> ans;

        auto backward = [&](this auto&& self, string s, int ri, int rj) -> void {
            int bal = 0;

            for (int i = ri; i >= 0; --i) {
                bal += (s[i] == ')') - (s[i] == '(');

                if (bal >= 0) continue;

                for (int j = rj; j >= i; --j) {
                    if (s[j] != '(' || (j < rj && s[j + 1] == '('))
                        continue;

                    self(s.substr(0, j) + s.substr(j + 1), i - 1, j - 1);
                }

                return;
            }

            ans.push_back(s);
        };

        auto forward = [&](this auto&& self, string s, int li, int lj) -> void {
            int bal = 0;

            for (int i = li; i < (int)s.size(); ++i) {
                bal += (s[i] == '(') - (s[i] == ')');

                if (bal >= 0) continue;

                for (int j = lj; j <= i; ++j) {
                    if (s[j] != ')' || (j > lj && s[j - 1] == ')'))
                        continue;

                    self(s.substr(0, j) + s.substr(j + 1), i, j);
                }

                return;
            }

            backward(s, (int)s.size() - 1, (int)s.size() - 1);
        };

        forward(s, 0, 0);
        return ans;
    }
};
